fn is_decimal_with_two_precision(s: &[u8]) -> bool {
    // Check if the length of the slice is less than 3
    if s.len() < 3 {
        return false;
    }
    
    // Check if the character at length - 3 is '.' and that there are two characters following it
    let len = s.len();
    s[len - 3] == b'.' && len >= 3 && len - 3 + 2 == len
}

